}

Method.Source:
/// <summary>
/// Packs an extension table record to the container field <C>PackedExtensions</C>.
/// </summary>
/// <param name="_METPurchTable">
/// The extension table record.
/// </param>
public void packMETPurchTable(METPurchTable _METPurchTable)
{
    _METPurchTable.PurchTable = this.RecId;
    this.SysExtensionSerializerMap::packExtensionTable(_METPurchTable);
}

    /// <summary>
    /// insert COC method
    /// </summary>
    /// <param name = "_interCompanySilent"> boolean value </param>
    /// <param name = "_accountingDate"> accounting date</param>
    void  insert(boolean _interCompanySilent ,
                 AccountingDate _accountingDate)
    {
        next insert(_interCompanySilent, _accountingDate);

        METPurchTable               METPurchTable;
        METVendSiteSettingsSetup    METVendSiteSettingsSetup = this.METFindMETVendSiteSettingsSetup();
        if(METVendSiteSettingsSetup)
        {
            METPurchTable.PurchTable    = this.RecId;
            METPurchTable.initFromVendSiteSettingsSetup(METVendSiteSettingsSetup);
            if(METPurchTable.validateWrite())
            {
                METPurchTable.insert();
            }
        }

    }

    /// <summary>
    /// Find method to fetch table buffer
    /// </summary>
    /// <returns>table buffer</returns>
    public METVendSiteSettingsSetup METFindMETVendSiteSettingsSetup()
    {
        METVendSiteSettingsSetup METVendSiteSettingsSetup;
        
        select firstonly1 METVendSiteSettingsSetup index VendSiteWHIndex 
            where (METVendSiteSettingsSetup.AssignedVendorAccount == this.OrderAccount 
            &&  METVendSiteSettingsSetup.AssignedSite == this.InventSiteId
            && METVendSiteSettingsSetup.AssignedWH == this.InventLocationId) 
            || (METVendSiteSettingsSetup.AssignedVendorAccount == this.OrderAccount 
            &&  METVendSiteSettingsSetup.AssignedSite == this.InventSiteId)
            || METVendSiteSettingsSetup.AssignedVendorAccount == this.OrderAccount;

        return METVendSiteSettingsSetup;
    }
